47			s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
48			s.bold = lipgloss.NewStyle().Bold(true)
49			s.dim = lipgloss.NewStyle().Faint(true)
50			s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
