71	// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
72	// It first checks the writer itself, then falls back to Stdout/Stderr.
73	func getTerminalWidth(w io.Writer) int {
74		// Try the output writer first
75		if f, ok := w.(*os.File); ok {
76			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
77				return min(width, 80)
78			}
79		}
80	
81		// Fall back to Stdout, then Stderr
82		for _, f := range []*os.File{os.Stdout, os.Stderr} {
83			if f == nil {
84				continue
85			}
86			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
87				return min(width, 80)
88			}
89		}
90	
91		return 60
92	}
