107	// totalTokens recursively sums all token fields including subagent tokens.
108	func totalTokens(tu *agent.TokenUsage) int {
109		if tu == nil {
110			return 0
111		}
112		total := saturatingIntAdd(tu.InputTokens, tu.CacheCreationTokens)
113		total = saturatingIntAdd(total, tu.CacheReadTokens)
114		total = saturatingIntAdd(total, tu.OutputTokens)
115		total = saturatingIntAdd(total, totalTokens(tu.SubagentTokens))
116		return total
117	}
