// trailStatusCell renders a status for the list table, coloring the terminal
// states when color is enabled (merged green for success, closed gray for
// inactive) and leaving open/draft default so the colored states stand out.
// The ANSI sequences are bracketed in tabwriter.Escape bytes so the StripEscape
// tabwriter keeps the columns aligned.
func trailStatusCell(styles statusStyles, status trail.Status) string {
	text := trailStatusDisplay(status)
	if !styles.colorEnabled {
		return text
	}
	var style lipgloss.Style
	switch status {
	case trail.StatusMerged:
		style = styles.green
	case trail.StatusClosed:
		style = styles.gray
	default:
		return text
	}
	return bracketTabwriterANSI(styles.render(style, text), text)
}

// bracketTabwriterANSI wraps the ANSI escape sequences in rendered (the styled
// form of plain) with tabwriter.Escape (0xff) bytes, so a StripEscape tabwriter
// passes them through without counting them toward cell width while the visible
// plain text stays countable. It returns the input unchanged when rendered
// carries no styling (color stripped, e.g. no TTY) or plain can't be located.
func bracketTabwriterANSI(rendered, plain string) string {
	if rendered == plain {
		return plain
	}
	idx := strings.Index(rendered, plain)
	if idx < 0 {
		return rendered
	}
	const esc = "\xff"
	prefix := rendered[:idx]
	suffix := rendered[idx+len(plain):]
	var b strings.Builder
	if prefix != "" {
		b.WriteString(esc)
		b.WriteString(prefix)
		b.WriteString(esc)
	}
	b.WriteString(plain)
	if suffix != "" {
		b.WriteString(esc)
		b.WriteString(suffix)
		b.WriteString(esc)
	}
	return b.String()
}

func TestBracketTabwriterANSI_BracketsEscapesAroundVisibleText(t *testing.T) {
	t.Parallel()
	got := bracketTabwriterANSI("\x1b[32mmerged\x1b[0m", "merged")
	want := "\xff\x1b[32m\xffmerged\xff\x1b[0m\xff"
	if got != want {
		t.Errorf("bracketTabwriterANSI = %q, want %q", got, want)
	}
}

func TestBracketTabwriterANSI_PassesThroughWhenUnstyled(t *testing.T) {
	t.Parallel()
	if got := bracketTabwriterANSI("merged", "merged"); got != "merged" {
		t.Errorf("bracketTabwriterANSI = %q, want unchanged %q", got, "merged")
	}
}

// TestBracketTabwriterANSI_PreservesColumnAlignment proves the 0xff bracketing
// keeps a StripEscape tabwriter aligned: the colored layout, with its escapes
// removed, must match the plain layout byte-for-byte.
func TestBracketTabwriterANSI_PreservesColumnAlignment(t *testing.T) {
	t.Parallel()
	render := func(status string) string {
		var b bytes.Buffer
		tw := tabwriter.NewWriter(&b, 0, 0, 2, ' ', tabwriter.StripEscape)
		fmt.Fprintf(tw, "%s\tEND\n", status)
		fmt.Fprintf(tw, "%s\tEND\n", "open")
		_ = tw.Flush()
		return b.String()
	}
	colored := render(bracketTabwriterANSI("\x1b[32mmerged\x1b[0m", "merged"))
	plain := render("merged")
	ansi := regexp.MustCompile("\x1b\\[[0-9;]*m")
	stripped := ansi.ReplaceAllString(strings.ReplaceAll(colored, "\xff", ""), "")
	if stripped != plain {
		t.Errorf("colored layout (escapes stripped) = %q, want %q", stripped, plain)
	}
}

// TestPrintTrailListPlainWhenNotATerminal guards the regression that list output
// to a non-terminal writer stays plain: no ANSI escapes, no tabwriter escape
// bytes.
func TestPrintTrailListPlainWhenNotATerminal(t *testing.T) {
	t.Parallel()
	var out bytes.Buffer
	printTrailList(&out, []*trail.Metadata{
		{Branch: "feat/a", Status: trail.StatusMerged, UpdatedAt: time.Now()},
		{Branch: "fix/b", Status: trail.StatusClosed, UpdatedAt: time.Now()},
	}, trailListDisplayOptions{StatusFilters: nil, TotalMatched: 2})

	text := out.String()
	if strings.Contains(text, "\x1b[") {
		t.Errorf("non-terminal list output should have no ANSI escapes, got:\n%q", text)
	}
	if strings.ContainsRune(text, '\xff') {
		t.Errorf("non-terminal list output should have no tabwriter escape bytes, got:\n%q", text)
	}
	for _, want := range []string{"merged", "closed"} {
		if !strings.Contains(text, want) {
			t.Errorf("output missing %q, got:\n%s", want, text)
		}
	}
}

