func printTrailRows(w io.Writer, trails []*trail.Metadata, showAuthor, showStatus bool) {
	styles := newStatusStyles(w)
	showPhase := trailListHasPhase(trails)
	showURL := trailListHasURL(trails)

	columns := []string{"NUM", "BRANCH", "TITLE"}
	statusCol := -1
	if showStatus {
		statusCol = len(columns)
		columns = append(columns, "STATUS")
	}
	if showPhase {
		columns = append(columns, "PHASE")
	}
	if showAuthor {
		columns = append(columns, "AUTHOR")
	}
	columns = append(columns, "UPDATED")
	if showURL {
		columns = append(columns, "URL")
	}

	header := "  " + strings.Join(columns, "\t")
	dataLines := make([]string, len(trails))
	// colorize[i] styles row i's STATUS cell, or is nil to leave it plain.
	colorize := make([]func(string) string, len(trails))
	anyColor := false
	for i, t := range trails {
		number := "-"
		if t.Number > 0 {
			number = strconv.Itoa(t.Number)
		}
		title := truncateOneLine(t.Title, 60)
		if title == "" {
			title = "(untitled)"
		}
		fields := []string{number, t.Branch, title}
		if showStatus {
			fields = append(fields, trailStatusDisplay(t.Status))
		}
		if showPhase {
			fields = append(fields, trailPhaseDisplay(t.Phase))
		}
		if showAuthor {
			fields = append(fields, t.AuthorLogin())
		}
		fields = append(fields, timeAgo(t.UpdatedAt))
		if showURL {
			fields = append(fields, t.URL)
		}
		dataLines[i] = "  " + strings.Join(fields, "\t")

		if styles.colorEnabled && statusCol >= 0 {
			if style, ok := trailStatusColor(styles, t.Status); ok {
				colorize[i] = func(value string) string { return styles.render(style, value) }
				anyColor = true
			}
		}
	}

	// Fast path: no colored status to splice in — straight tabwriter, output
	// byte-identical to the historical (uncolored) rendering.
	if !anyColor {
		writeTabTable(w, header, dataLines)
		return
	}

	// Color path: tabwriter counts ANSI escape bytes toward cell width (escaped
	// segments are not exempt), so coloring a cell before layout shifts every
	// column after it. Instead, lay out plain text, then splice color into the
	// exact STATUS span — located via a sentinel mask so layout is preserved and
	// matches are collision-free.
	plain := tabTableLines(header, dataLines)
	maskLines := make([]string, len(trails))
	for i := range trails {
		maskLines[i] = dataLines[i]
		if colorize[i] != nil {
			maskLines[i] = maskStatusCell(header, columns, trails[i], statusCol, showPhase, showAuthor, showURL)
		}
	}
	mask := tabTableLines(header, maskLines)
	for _, line := range spliceColumnColor(plain, mask, colorize) {
		fmt.Fprintln(w, line)
	}
}

// writeTabTable renders header + dataLines through a tabwriter with the trail
// list's column layout (2-space gutter). It is the single layout definition
// shared by the colored and uncolored paths.
func writeTabTable(w io.Writer, header string, dataLines []string) {
	// tabwriter aligns by display columns (runes), so multi-byte branch names or
	// logins don't throw off the table.
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, header)
	for _, line := range dataLines {
		fmt.Fprintln(tw, line)
	}
	_ = tw.Flush()
}

// tabTableLines lays out the table and returns it split into lines (header
// first, then one line per data row), dropping the trailing empty line.
func tabTableLines(header string, dataLines []string) []string {
	var b strings.Builder
	writeTabTable(&b, header, dataLines)
	lines := strings.Split(b.String(), "\n")
	if n := len(lines); n > 0 && lines[n-1] == "" {
		lines = lines[:n-1]
	}
	return lines
}

// maskStatusCell rebuilds a data row with its STATUS cell replaced by a
// same-length run of the sentinel byte (0x01), so the mask lays out identically
// to the real row and marks the STATUS span for spliceColumnColor.
func maskStatusCell(_ string, _ []string, t *trail.Metadata, statusCol int, showPhase, showAuthor, showURL bool) string {
	number := "-"
	if t.Number > 0 {
		number = strconv.Itoa(t.Number)
	}
	title := truncateOneLine(t.Title, 60)
	if title == "" {
		title = "(untitled)"
	}
	fields := []string{number, t.Branch, title}
	fields = append(fields, strings.Repeat("\x01", len([]rune(trailStatusDisplay(t.Status)))))
	if showPhase {
		fields = append(fields, trailPhaseDisplay(t.Phase))
	}
	if showAuthor {
		fields = append(fields, t.AuthorLogin())
	}
	fields = append(fields, timeAgo(t.UpdatedAt))
	if showURL {
		fields = append(fields, t.URL)
	}
	_ = statusCol
	return "  " + strings.Join(fields, "\t")
}

// spliceColumnColor recolors one column on each line whose colorize entry is
// non-nil. The mask lines mark that column's span with sentinel bytes (0x01);
// because mask and plain share an identical layout, the sentinel's byte span in
// mask is the value's byte span in plain. colorize is indexed by data row;
// plain/mask carry the header at index 0, so data row i is line i+1.
func spliceColumnColor(plain, mask []string, colorize []func(string) string) []string {
	out := append([]string(nil), plain...)
	for i, fn := range colorize {
		if fn == nil {
			continue
		}
		line := i + 1
		if line >= len(out) || line >= len(mask) {
			continue
		}
		start := strings.IndexByte(mask[line], '\x01')
		end := strings.LastIndexByte(mask[line], '\x01') + 1
		if start < 0 || end <= start || end > len(out[line]) {
			continue
		}
		out[line] = out[line][:start] + fn(out[line][start:end]) + out[line][end:]
	}
	return out
}

