// trailStatusCell renders a status for the list table, coloring the terminal
// states when color is enabled (merged green for success, closed gray for
// inactive) and leaving open/draft default so the colored states stand out.
// The ANSI sequences are bracketed in tabwriter.Escape bytes so the StripEscape
// tabwriter keeps the columns aligned.
func trailStatusCell(styles statusStyles, status trail.Status) string {
	text := trailStatusDisplay(status)
	if !styles.colorEnabled {
		return text
	}
	var style lipgloss.Style
	switch status {
	case trail.StatusMerged:
		style = styles.green
	case trail.StatusClosed:
		style = styles.gray
	default:
		return text
	}
	return bracketTabwriterANSI(styles.render(style, text), text)
}

// bracketTabwriterANSI wraps the ANSI escape sequences in rendered (the styled
// form of plain) with tabwriter.Escape (0xff) bytes, so a StripEscape tabwriter
// passes them through without counting them toward cell width while the visible
// plain text stays countable. It returns the input unchanged when rendered
// carries no styling (color stripped, e.g. no TTY) or plain can't be located.
func bracketTabwriterANSI(rendered, plain string) string {
	if rendered == plain {
		return plain
	}
	idx := strings.Index(rendered, plain)
	if idx < 0 {
		return rendered
	}
	const esc = "\xff"
	prefix := rendered[:idx]
	suffix := rendered[idx+len(plain):]
	var b strings.Builder
	if prefix != "" {
		b.WriteString(esc)
		b.WriteString(prefix)
		b.WriteString(esc)
	}
	b.WriteString(plain)
	if suffix != "" {
		b.WriteString(esc)
		b.WriteString(suffix)
		b.WriteString(esc)
	}
	return b.String()
}

