// TestBracketTabwriterANSI_PreservesColumnAlignment proves the 0xff bracketing
// keeps a StripEscape tabwriter aligned: the colored layout, with its escapes
// removed, must match the plain layout byte-for-byte.
func TestBracketTabwriterANSI_PreservesColumnAlignment(t *testing.T) {
	t.Parallel()
	render := func(status string) string {
		var b bytes.Buffer
		tw := tabwriter.NewWriter(&b, 0, 0, 2, ' ', tabwriter.StripEscape)
		fmt.Fprintf(tw, "%s\tEND\n", status)
		fmt.Fprintf(tw, "%s\tEND\n", "open")
		_ = tw.Flush()
		return b.String()
	}
	colored := render(bracketTabwriterANSI("\x1b[32mmerged\x1b[0m", "merged"))
	plain := render("merged")
	ansi := regexp.MustCompile("\x1b\\[[0-9;]*m")
	stripped := ansi.ReplaceAllString(strings.ReplaceAll(colored, "\xff", ""), "")
	if stripped != plain {
		t.Errorf("colored layout (escapes stripped) = %q, want %q", stripped, plain)
	}
}

