// TestSpliceColumnColor_RecolorsExactSpanAndPreservesAlignment proves the
// sentinel-mask splice colors the right cell, is collision-free against a
// duplicate token elsewhere in the row, and preserves column alignment (the
// colored layout with ANSI stripped is byte-identical to the plain layout).
func TestSpliceColumnColor_RecolorsExactSpanAndPreservesAlignment(t *testing.T) {
	t.Parallel()
	cols := []string{"NUM", "BRANCH", "TITLE", "STATUS", "UPDATED"}
	statusCol := 3
	// Row 0's TITLE contains the word "merged" to catch naive substring matches;
	// only the STATUS cell should be colored. Row 1 has an empty BRANCH cell to
	// exercise span location with adjacent padding.
	dataFields := [][]string{
		{"1", "feat/long-branch", "merged conflict fix", "merged", "2h ago"},
		{"2", "", "short", "open", "1d ago"},
	}
	header := "  " + strings.Join(cols, "\t")
	dataLines := make([]string, len(dataFields))
	maskLines := make([]string, len(dataFields))
	colorize := make([]func(string) string, len(dataFields))
	for i, f := range dataFields {
		dataLines[i] = "  " + strings.Join(f, "\t")
		masked := append([]string(nil), f...)
		if f[statusCol] == "merged" {
			masked[statusCol] = strings.Repeat("\x01", len([]rune(f[statusCol])))
			colorize[i] = func(v string) string { return "\x1b[32m" + v + "\x1b[0m" }
		}
		maskLines[i] = "  " + strings.Join(masked, "\t")
	}
	plain := tabTableLines(header, dataLines)
	mask := tabTableLines(header, maskLines)
	got := spliceColumnColor(plain, mask, colorize)

	if !strings.Contains(got[1], "\x1b[32mmerged\x1b[0m") {
		t.Errorf("row 0 STATUS should be colored, got: %q", got[1])
	}
	if strings.Contains(got[1], "\x1b[32mmerged conflict") {
		t.Errorf("the TITLE 'merged' must not be colored, got: %q", got[1])
	}
	ansi := regexp.MustCompile("\x1b\\[[0-9;]*m")
	for i := range got {
		if stripped := ansi.ReplaceAllString(got[i], ""); stripped != plain[i] {
			t.Errorf("line %d misaligned: %q (want plain %q)", i, stripped, plain[i])
		}
	}
}

