// trailStatusColor returns the style for a colorable terminal status — merged
// green (success), closed gray (inactive) — and false for open/draft and any
// other status, which stay default so the colored states stand out.
func trailStatusColor(styles statusStyles, status trail.Status) (lipgloss.Style, bool) {
	switch status {
	case trail.StatusMerged:
		return styles.green, true
	case trail.StatusClosed:
		return styles.gray, true
	case trail.StatusDraft, trail.StatusOpen:
		return lipgloss.Style{}, false
	default:
		return lipgloss.Style{}, false
	}
}

