// trailStatusColor returns the style for a trail status, GitHub-style: open
// green, merged magenta, closed red, draft gray/dim. An unknown status returns
// false and stays default. These avoid AUTHOR's cyan and PHASE's yellow so the
// columns stay distinguishable.
func trailStatusColor(styles statusStyles, status trail.Status) (lipgloss.Style, bool) {
	switch status {
	case trail.StatusOpen:
		return styles.green, true
	case trail.StatusMerged:
		return styles.magenta, true
	case trail.StatusClosed:
		return styles.red, true
	case trail.StatusDraft:
		return styles.gray, true
	default:
		return lipgloss.Style{}, false
	}
}

