// TestTrailStatusColor_OnlyColorsTerminalStates verifies the trail-specific
// mapping: merged and closed are colored, open/draft and unknown stay default.
func TestTrailStatusColor_OnlyColorsTerminalStates(t *testing.T) {
	t.Parallel()
	styles := newStatusStyles(&bytes.Buffer{}) // color disabled, but mapping is independent of that
	cases := map[trail.Status]bool{
		trail.StatusMerged: true,
		trail.StatusClosed: true,
